CREATE OR REPLACE FUNCTION public.complete_sale_once(p_client_ref text,p_items jsonb,p_payments jsonb,p_discount numeric,p_currency text,p_customer uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.sales; result jsonb; BEGIN IF NOT public.is_staff(auth.uid()) THEN RAISE EXCEPTION 'Not authorised'; END IF; IF coalesce(p_client_ref,'')='' OR length(p_client_ref)>120 THEN RAISE EXCEPTION 'Invalid sale reference'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(public.current_store_id()::text || ':' || auth.uid()::text || ':' || p_client_ref,0)); SELECT * INTO s FROM public.sales WHERE store_id=public.current_store_id() AND cashier_id=auth.uid() AND client_ref=p_client_ref; IF FOUND THEN RETURN jsonb_build_object('id',s.id,'sale_number',s.sale_number,'total',s.total,'change',s.change_given,'rate',s.exchange_rate,'duplicate',true); END IF; result:=public.complete_sale(p_items,p_payments,p_discount,p_currency,p_customer); UPDATE public.sales SET client_ref=p_client_ref WHERE id=(result->>'id')::uuid AND cashier_id=auth.uid() AND store_id=public.current_store_id(); IF NOT FOUND THEN RAISE EXCEPTION 'Sale reference could not be saved'; END IF; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.complete_sale_once(text,jsonb,jsonb,numeric,text,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.complete_sale_once(text,jsonb,jsonb,numeric,text,uuid) TO authenticated;
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.complete_offline_sale(text,jsonb,jsonb,numeric,text,timestamp with time zone,uuid)'::regprocedure) INTO d; d:=replace(d,'select id, sale_number into v_existing from sales where client_ref', 'PERFORM pg_advisory_xact_lock(hashtextextended(public.current_store_id()::text || '':'' || auth.uid()::text || '':'' || p_client_ref,0)); select id, sale_number into v_existing from sales where client_ref'); EXECUTE d; END $$;